import java.math.BigDecimal
import java.math.RoundingMode

class Ledger {
    private val balances = HashMap<String, BigDecimal>()
    private val log = HashMap<String, MutableList<BigDecimal>>()

    companion object {
        private val SCALE = 2
    }

    fun openAccount(id: String, initial: BigDecimal = BigDecimal.ZERO) {
        if (balances.containsKey(id)) {
            throw IllegalArgumentException("Account $id already exists")
        }
        balances[id] = initial.setScale(SCALE, RoundingMode.HALF_UP)
        log[id] = mutableListOf()
    }

    fun balance(id: String): BigDecimal {
        val bal = balances[id] ?: throw NoSuchElementException("Account $id not found")
        return bal.setScale(SCALE, RoundingMode.HALF_UP)
    }

    fun transfer(from: String, to: String, amount: BigDecimal) {
        if (amount.compareTo(BigDecimal.ZERO) <= 0) {
            throw IllegalArgumentException("Amount must be positive")
        }
        val validatedAmount = amount.setScale(SCALE, RoundingMode.HALF_UP)

        val fromBal = balances[from] ?: throw NoSuchElementException("Account $from not found")
        val toBal = balances[to] ?: throw NoSuchElementException("Account $to not found")

        if (fromBal.compareTo(validatedAmount) < 0) {
            throw IllegalStateException("insufficient funds")
        }

        // Perform the transfer atomically after validation
        balances[from] = fromBal - validatedAmount
        log.getValue(from).add(-validatedAmount)

        balances[to] = toBal + validatedAmount
        log.getValue(to).add(validatedAmount)
    }

    fun history(id: String): List<BigDecimal> {
        val entries = log[id] ?: throw NoSuchElementException("Account $id not found")
        return entries.map { it.setScale(SCALE, RoundingMode.HALF_UP) }
    }

    companion object {
        fun split(total: BigDecimal, n: Int): List<BigDecimal> {
            if (n <= 0) {
                throw IllegalArgumentException("n must be positive")
            }
            val validatedTotal = total.setScale(SCALE, RoundingMode.HALF_UP)
            val part = validatedTotal.divide(BigDecimal(n), SCALE, RoundingMode.DOWN)
            val remainder = validatedTotal - (part * n)

            // Create list with 'part' for all, then add 1 cent to the first 'remainder' entries
            // The larger parts should come first. Since remainder is in cents (0..n-1),
            // we distribute the extra cents to the first 'remainder' entries.
            val result = mutableListOf<BigDecimal>()
            for (i in 0 until n) {
                if (i < remainder.toInt()) {
                    result.add(part + BigDecimal("0.01"))
                } else {
                    result.add(part)
                }
            }
            return result
        }
    }
}
