```kotlin
fun toJson(value: Any?, indent: Int = 0): String {
    val sb = StringBuilder()
    serializeValue(value, sb, indent, 0)
    return sb.toString()
}

private fun serializeValue(
    value: Any?,
    sb: StringBuilder,
    indent: Int,
    level: Int
) {
    when (value) {
        null -> sb.append("null")
        is Boolean -> sb.append(if (value) "true" else "false")
        is String -> serializeString(value, sb)
        is Int -> sb.append(value)
        is Long -> sb.append(value)
        is Double -> serializeDouble(value, sb)
        is Float -> serializeDouble(value.toDouble(), sb)
        is Map<*, *> -> serializeMap(value as Map<*, *>, sb, indent, level)
        is List<*> -> serializeList(value, sb, indent, level)
        is Array<*> -> serializeList(value.toList(), sb, indent, level)
        is Enum<*> -> serializeString(value.name, sb)
        else -> throw IllegalArgumentException("Unsupported type: ${value::class.java.name}")
    }
}

private fun serializeDouble(value: Double, sb: StringBuilder) {
    if (value.isNaN() || value.isInfinite()) {
        throw IllegalArgumentException("Non-finite double values are not supported")
    }
    sb.append(value.toString())
}

private fun escapeChar(c: Char): String {
    return when (c) {
        '"' -> "\\\""
        '\\' -> "\\\\"
        '\b' -> "\\b"
        '\f' -> "\\f"
        '\n' -> "\\n"
        '\r' -> "\\r"
        '\t' -> "\\t"
        in 0x00..0x1F -> String.format("\\u%04x", c.toInt())
        else -> c.toString()
    }
}

private fun serializeString(value: String, sb: StringBuilder) {
    sb.append('"')
    for (c in value) {
        sb.append(escapeChar(c))
    }
    sb.append('"')
}

private fun getIndent(level: Int, indent: Int): String {
    if (indent <= 0) return ""
    return " ".repeat(level * indent)
}

private fun serializeMap(
    map: Map<*, *>,
    sb: StringBuilder,
    indent: Int,
    level: Int
) {
    if (map.isEmpty()) {
        sb.append("{}")
        return
    }

    // Validate keys are Strings
    for (key in map.keys) {
        if (key !is String) {
            throw IllegalArgumentException("Map keys must be Strings, got: ${key::class.java.name}")
        }
    }

    if (indent <= 0) {
        sb.append("{")
        var first = true
        for ((key, value) in map) {
            if (!first) sb.append(",")
            first = false
            serializeString(key as String, sb)
            sb.append(":")
            serializeValue(value, sb, indent, level + 1)
        }
        sb.append("}")
    } else {
        sb.append("{\n")
        var first = true
        for ((key, value) in map) {
            if (!first) sb.append(",\n")
            first = false
            val currentIndent = getIndent(level + 1, indent)
            sb.append(currentIndent)
            serializeString(key as String, sb)
            sb.append(": ")
            serializeValue(value, sb, indent, level + 1)
        }
        sb.append("\n")
        sb.append(getIndent(level, indent))
        sb.append("}")
    }
}

private fun serializeList(
    list: List<*>,
    sb: StringBuilder,
    indent: Int,
    level: Int
) {
    if (list.isEmpty()) {
        sb.append("[]")
        return
    }

    if (indent <= 0) {
        sb.append("[")
        var first = true
        for (item in list) {
            if (!first) sb.append(",")
            first = false
            serializeValue(item, sb, indent, level + 1)
        }
        sb.append("]")
    } else {
        sb.append("[\n")
        var first = true
        for (item in list) {
            if (!first) sb.append(",\n")
            first = false
            val currentIndent = getIndent(level + 1, indent)
            sb.append(currentIndent)
            serializeValue(item, sb, indent, level + 1)
        }
        sb.append("\n")
        sb.append(getIndent(level, indent))
        sb.append("]")
    }
}
