sealed class Token {
    abstract val pos: Int  // 0-based index of the token's first character
    data class Ident(val name: String, override val pos: Int) : Token()
    data class Str(val value: String, override val pos: Int) : Token()
    data class Num(val value: Double, override val pos: Int) : Token()
    data class Op(val symbol: String, override val pos: Int) : Token()
    data class Paren(val open: Boolean, override val pos: Int) : Token()
}
class TokenizeException(message: String, val pos: Int) : Exception(message)

fun tokenize(input: String): List<Token> {
    val tokens = mutableListOf<Token>()
    var i = 0
    val len = input.length

    // Determine if a number can start here (leading minus allowed)
    fun canHaveLeadingMinus(): Boolean {
        return tokens.isEmpty() || 
               (tokens.last() is Token.Op) || 
               (tokens.last() is Token.Paren && tokens.last().open)
    }

    while (i < len) {
        val c = input[i]

        // Skip whitespace
        if (c == ' ' || c == '\t' || c == '\n') {
            i++
            continue
        }

        when {
            // Identifiers: [A-Za-z_][A-Za-z0-9_.]*
            c.isLetter() || c == '_' -> {
                val start = i
                var j = i + 1
                while (j < len) {
                    val ch = input[j]
                    if (ch.isLetterOrDigit() || ch == '.' || ch == '_') {
                        // Dot is only allowed after the first character, which we've already handled by starting loop at i+1
                        // But wait: the rule says [A-Za-z_][A-Za-z0-9_.]* so dot is allowed in subsequent chars.
                        j++
                    } else {
                        break
                    }
                }
                val name = input.substring(start, j)
                tokens.add(Token.Ident(name, start))
                i = j
            }

            // Numbers: optional leading - (if allowed), then digits with optional fraction
            c == '-' && canHaveLeadingMinus() -> {
                val start = i
                var j = i + 1
                if (j >= len || !input[j].isDigit()) {
                    throw TokenizeException("Invalid number or unexpected '-'", start)
                }
                // Parse digits before decimal point
                while (j < len && input[j].isDigit()) {
                    j++
                }

                var hasDot = false
                if (j < len && input[j] == '.') {
                    // Check for "5." case: digit immediately followed by dot and then non-digit or end
                    if (j + 1 >= len || !input[j + 1].isDigit()) {
                        throw TokenizeException("Invalid number", start)
                    }
                    hasDot = true
                    j++ // skip the dot

                    // Parse digits after decimal point
                    while (j < len && input[j].isDigit()) {
                        j++
                    }
                } else if (!hasDot) {
                    // Just an integer part, no dot
                }

                val numStr = input.substring(start, j)
                try {
                    val value = numStr.toDouble()
                    tokens.add(Token.Num(value, start))
                } catch (e: NumberFormatException) {
                    throw TokenizeException("Invalid number", start)
                }
                i = j
            }

            // Numbers without leading minus: digits or dot followed by digit (.5)
            c.isDigit() || (c == '.' && i + 1 < len && input[i + 1].isDigit()) -> {
                val start = i
                var j = i

                // If starts with dot, it must be .5 form
                if (c == '.') {
                    j++ // skip dot
                    while (j < len && input[j].isDigit()) {
                        j++
                    }
                } else {
                    // Starts with digit
                    while (j < len && input[j].isDigit()) {
                        j++
                    }

                    if (j < len && input[j] == '.') {
                        // Check for "5." case
                        if (j + 1 >= len || !input[j + 1].isDigit()) {
                            throw TokenizeException("Invalid number", start)
                        }
                        j++ // skip dot
                        while (j < len && input[j].isDigit()) {
                            j++
                        }
                    }
                }

                val numStr = input.substring(start, j)
                try {
                    val value = numStr.toDouble()
                    tokens.add(Token.Num(value, start))
                } catch (e: NumberFormatException) {
                    throw TokenizeException("Invalid number", start)
                }
                i = j
            }

            // Strings: single or double quotes
            c == '"' || c == '\'' -> {
                val start = i
                val quoteChar = c
                var j = i + 1
                val sb = StringBuilder()

                while (j < len) {
                    val ch = input[j]
                    if (ch == '\\') {
                        if (j + 1 >= len) {
                            throw TokenizeException("Unterminated string", start)
                        }
                        val nextCh = input[j + 1]
                        when (nextCh) {
                            'n' -> sb.append('\n')
                            't' -> sb.append('\t')
                            'r' -> sb.append('\r')
                            '\\' -> sb.append('\\')
                            '\'' -> sb.append('\'')
                            '"' -> sb.append('"')
                            else -> sb.append(nextCh) // Any other escaped char stands for itself
                        }
                        j += 2
                    } else if (ch == quoteChar) {
                        break
                    } else {
                        sb.append(ch)
                        j++
                    }
                }

                if (j >= len || input[j] != quoteChar) {
                    throw TokenizeException("Unterminated string", start)
                }

                // Skip the closing quote
                j++
                tokens.add(Token.Str(sb.toString(), start))
                i = j
            }

            // Operators: longest match first
            input.startsWith("==", i) || input.startsWith("!=", i) || 
            input.startsWith("<=", i) || input.startsWith(">=", i) || 
            input.startsWith("<", i) || input.startsWith(">", i) || 
            input.startsWith("&&", i) || input.startsWith("||", i) || 
            input.startsWith("!", i) -> {
                val start = i
                var op = ""
                if (input.startsWith("==", i)) { op = "=="; i += 2 }
                else if (input.startsWith("!=", i)) { op = "!="; i += 2 }
                else if (input.startsWith("<=", i)) { op = "<="; i += 2 }
                else if (input.startsWith(">=", i)) { op = ">="; i += 2 }
                else if (input.startsWith("&&", i)) { op = "&&"; i += 2 }
                else if (input.startsWith("||", i)) { op = "||"; i += 2 }
                else if (input.startsWith("<", i)) { op = "<"; i++ }
                else if (input.startsWith(">", i)) { op = ">"; i++ }
                else if (input.startsWith("!", i)) { op = "!"; i++ }

                tokens.add(Token.Op(op, start))
            }

            // Parentheses
            c == '(' -> {
                tokens.add(Token.Paren(true, i))
                i++
            }
            c == ')' -> {
                tokens.add(Token.Paren(false, i))
                i++
            }

            // Anything else is an error
            else -> {
                throw TokenizeException("Unexpected character: $c", i)
            }
        }
    }

    return tokens
}
