                    body.append(bl)
                    i += 1

            hunks.append({
                'old_start': old_start,
                'old_count': old_count,
                'new_start': new_start,
                'new_count': new_count,
                'body': body
            })
        else:
            i += 1

    return hunks


def apply_patch(original: str, diff: str) -> str:
