                if orig_line.endswith('\n'):
                    orig_content = orig_line[:-1]
                else:
                    orig_content = orig_line

                if orig_content != content:
                    raise ValueError(
                        f"Hunk {hunk_idx + 1}: Removed line mismatch at line {current_line + 1}. "
                        f"Expected '{content}', got '{orig_content}'"
                    )

                current_line += 1

            elif bl.startswith('+'):
                content = bl[1:]
                idx = sum(1 for b in processed_body[:processed_body.index(bl)] if b.startswith('+'))

                if idx in new_no_newline:
                    result_lines.append(content)
                else:
                    result_lines.append(content + '\n')

    # Join result lines
    result = ''.join(result_lines)

    return result
