def parse_diff(diff: str) -> list:
    """Parse a unified diff into a list of hunk dictionaries."""
    diff_lines = diff.split('\n')
    hunks = []
    i = 0

    while i < len(diff_lines):
        line = diff_lines[i]
        if line.startswith('@@'):
            match = re.match(r'^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@', line)
            if not match:
                raise ValueError(f"Invalid hunk header: {line}")

            old_start = int(match.group(1))
            old_count = int(match.group(2)) if match.group(2) is not None else 1
            new_start = int(match.group(3))
            new_count = int(match.group(4)) if match.group(4) is not None else 1

            i += 1
            body = []

            while i < len(diff_lines):
                bl = diff_lines[i]

                # Check for end of hunk - look for next hunk header or file headers
                if bl.startswith('@@'):
                    break
                elif bl.startswith('diff --git') or bl.startswith('index '):
                    break
                elif bl.startswith('--- ') or bl.startswith('+++ '):
                    # These are file headers, skip them but don't break
                    # Actually, we should just skip them and continue
                    i += 1
                    continue
                else:
                    body.append(bl)
                    i += 1

            hunks.append({
                'old_start': old_start,
                'old_count': old_count,
                'new_start': new_start,
                'new_count': new_count,
                'body': body
            })
        else:
            i += 1

    return hunks
