import copy


def merge(base: dict, *overrides: dict) -> dict:
    """
    Deep merge configuration layers where later overrides win.

    - Dicts are merged recursively.
    - Any other value in an override replaces the base value (lists are replaced, not concatenated).
    - A key whose override value is None deletes that key from the result.
    - A key ending in '+' appends items to a base list. The '+' suffix is stripped and never appears in the result.
    - Inputs are not mutated; the result is a deep copy with no shared mutable objects.
    """

    def _deep_merge(base_dict, override_dict):
        """Recursively merge override_dict into base_dict."""
        # Start with a deep copy of base_dict to avoid mutation and sharing
        result = copy.deepcopy(base_dict)

        for key, override_value in override_dict.items():
            if key.endswith('+'):
                # Handle append semantics
                list_key = key[:-1]  # Strip the '+' suffix

                # Check if the list_key exists in the base (original or already merged)
                if list_key in result:
                    base_val = result[list_key]
                    if not isinstance(base_val, list):
                        raise TypeError(f"Cannot append to non-list value for key '{list_key}'")
                    # Append the override value to the existing list
                    # The override value should be a list; we deepcopy it
                    if override_value is None:
                        # If override is None, delete the key? Let's check spec: 
                        # "A key whose override value is None deletes that key from the result."
                        # But this is for keys ending in +. Let me re-read.
                        # The spec says: "A key whose override value is None deletes that key from the result."
                        # This applies generally. So if we have {"plugins+": None}, it should delete "plugins"?
                        # Actually, the append semantics say: `{"plugins+": ["x"]}` appends.
                        # If override_value is None for a + key, what happens?
                        # Let's interpret: the None check comes before or alongside? 
                        # The spec lists them as separate rules. I think None takes precedence for deletion.
                        del result[list_key]
                    else:
                        if not isinstance(override_value, list):
                            raise TypeError(f"Expected a list for append operation on key '{list_key}', got {type(override_value)}")
                        # Append each item (deep copied) to the base list
                        for item in override_value:
                            result[list_key].append(copy.deepcopy(item))
                else:
                    # Base doesn't have the key, create a new list from the override
                    if override_value is None:
                        # Nothing to do, key doesn't exist
                        pass
                    else:
                        if not isinstance(override_value, list):
                            raise TypeError(f"Expected a list for append operation on key '{list_key}', got {type(override_value)}")
                        result[list_key] = [copy.deepcopy(item) for item in override_value]
            elif override_value is None:
                # Delete the key from the result if it exists
                if key in result:
                    del result[key]
            else:
                # Normal merge
                if isinstance(override_value, dict) and key in result and isinstance(result[key], dict):
                    # Recursively merge dicts
                    result[key] = _deep_merge(result[key], override_value)
                else:
                    # Replace the value (deep copy to avoid sharing)
                    result[key] = copy.deepcopy(override_value)

        return result

    if not base:
        base = {}

    # Start with a deep copy of base
    result = copy.deepcopy(base)

    for override in overrides:
        if override is None:
            continue
        result = _deep_merge(result, override)

    return result
