def flatten(obj, sep="."):
    """
    Flatten a nested dict (and lists) into a flat dict with path keys.

    Args:
        obj: The top-level object must be a dict.
        sep: Separator for joining path segments.

    Returns:
        A flat dict with string keys representing paths to leaf values.

    Raises:
        TypeError: If the top-level object is not a dict.
        ValueError: If any key contains the separator character.
    """
    if not isinstance(obj, dict):
        raise TypeError("Top-level object must be a dict")

    result = {}

    def _flatten(current, path_parts):
        if isinstance(current, dict):
            if len(current) == 0:
                # Empty dict is kept as a leaf value
                key = sep.join(path_parts)
                result[key] = current
                return

            for k, v in current.items():
                if not isinstance(k, str):
                    raise ValueError("Keys must be strings")
                if sep in k:
                    raise ValueError(f"Key '{k}' contains separator '{sep}'")

                new_path_parts = path_parts + [k]
                _flatten(v, new_path_parts)
        elif isinstance(current, list):
            if len(current) == 0:
                # Empty list is kept as a leaf value
                key = sep.join(path_parts)
                result[key] = current
                return

            for i, v in enumerate(current):
                new_path_parts = path_parts + [str(i)]
                _flatten(v, new_path_parts)
        else:
            # Any other value is a leaf
            key = sep.join(path_parts)
            result[key] = current

    _flatten(obj, [])
    return result


def unflatten(flat: dict, sep="."):
    """
    Unflatten a flat dict back into a nested structure of dicts and lists.

    Args:
        flat: A flat dict with path keys.
        sep: Separator used in the path keys.

    Returns:
        A nested dict/list structure.

    Raises:
        ValueError: If list indices are not dense, or if there are conflicts
                    (e.g., a key and its prefix both exist as leaf values).
    """
    if not isinstance(flat, dict):
        raise TypeError("Input must be a dict")

    # Parse all keys into path segments
    parsed_keys = []
    for key in flat:
        if not isinstance(key, str):
            raise ValueError("Keys must be strings")
        if sep in key:
            parts = key.split(sep)
        else:
            parts = [key]

        # Validate that all parts are either valid dict keys or valid list indices
        path = []
        for part in parts:
            # Check if it's a valid non-negative integer without leading zeros
            if part == "0" or (part.isdigit() and len(part) > 0 and part[0] != '0'):
                path.append(int(part))
            else:
                path.append(part)
        parsed_keys.append((path, flat[key]))

    # Sort by path length first, then lexicographically for consistent processing
    # Actually, we need to process in an order that ensures parents are created before children
    # Sorting by the path tuple works well since shorter paths come first naturally
    # But we need to be careful: (a, 0) vs (a, b) - both have same length prefix

    parsed_keys.sort(key=lambda x: x[0])

    root = {}

    for path, value in parsed_keys:
        if not path:
            raise ValueError("Empty path")

        # Navigate to the parent container
        current = root
        is_conflict = False

        for i, segment in enumerate(path[:-1]):
            next_segment = path[i + 1]

            if isinstance(segment, int):
                # This should be a list
                if not isinstance(current, list):
                    raise ValueError(f"Conflict: expected list at index {segment}, but found dict")
                if segment < 0 or segment >= len(current):
                    raise ValueError(f"List index {segment} out of range")
                current = current[segment]
            else:
                # This should be a dict
                if not isinstance(current, dict):
                    raise ValueError(f"Conflict: expected dict at key '{segment}', but found list")
                if segment in current:
                    existing = current[segment]
                    # Check if there's a conflict: both a leaf and a container with the same path prefix
                    # We'll handle this by checking if the existing value is a leaf vs a container
                    # But actually, the conflict check is: if we have {"a": 1} and {"a.b": 2}, then when processing "a", we set it to 1. When processing "a.b", we try to access current["a"] which is 1 (not a dict). So this should raise an error naturally.
                    pass
                if segment not in current:
                    # Determine what type the next container should be based on the next segment
                    if isinstance(next_segment, int):
                        current[segment] = []
                    else:
                        current[segment] = {}
                current = current[segment]

        # Now set the final value
        last_segment = path[-1]
        if isinstance(last_segment, int):
            # Should be a list
            if not isinstance(current, list):
                raise ValueError(f"Conflict: expected list at index {last_segment}")
            if last_segment < 0 or last_segment >= len(current):
                raise ValueError(f"List index {last_segment} out of range")
            current[last_segment] = value
        else:
            # Should be a dict
            if not isinstance(current, dict):
                raise ValueError(f"Conflict: expected dict at key '{last_segment}'")
            if last_segment in current:
                raise ValueError(f"Duplicate key '{last_segment}' at path {sep.join(path[:-1])}")
            current[last_segment] = value

    # Validate that all lists are dense (indices 0..n-1)
    def _validate_lists(obj):
        if isinstance(obj, list):
            for i, item in enumerate(obj):
                if not isinstance(item, dict) and not isinstance(item, list):
                    continue
                _validate_lists(item)
            # Check density: indices must be 0..len-1
            expected_indices = set(range(len(obj)))
            actual_indices = set(range(len(obj)))
            if expected_indices != actual_indices:
                raise ValueError(f"List is not dense")
        elif isinstance(obj, dict):
            for v in obj.values():
                _validate_lists(v)

    _validate_lists(root)

    return root
