import math
from typing import Union


def evaluate(expr: str, env: dict[str, float] | None = None) -> int | float:
    """
    Evaluate a small expression language.

    Grammar (lowest to highest precedence):
    1. Conditional: a ? b : c (right-associative)
    2. Logical OR || and AND && (short-circuit, result 0 or 1)
    3. Comparisons == != < <= > >= (non-associative, result 0 or 1)
    4. Addition + - (left-associative)
    5. Multiplication * / % (left-associative)
    6. Unary -, +, ! 
    7. Power ^ (right-associative)
    8. Atoms: literals, identifiers, function calls, parentheses
    """
    if env is None:
        env = {}

    # Tokenizer
    tokens = _tokenize(expr)

    # Parser with recursive descent
    parser = _Parser(tokens, env)
    result = parser.parse_expression()

    # Check for trailing tokens
    if parser.pos < len(parser.tokens):
        raise SyntaxError(f"Unexpected token: {parser.tokens[parser.pos]}")

    return result


class _Token:
    def __init__(self, kind: str, value: Union[str, int, float], pos: int = 0):
        self.kind = kind  # 'INT', 'FLOAT', 'IDENT', 'OP', 'LPAREN', 'RPAREN', 'QUESTION', 'COLON', 'EOF'
        self.value = value
        self.pos = pos

    def __repr__(self):
        return f"Token({self.kind}, {self.value!r})"


def _tokenize(expr: str) -> list[_Token]:
    """Tokenize the expression string."""
    tokens = []
    i = 0
    n = len(expr)

    while i < n:
        c = expr[i]

        # Skip whitespace
        if c in ' \t\n\r':
            i += 1
            continue

        # Integer literal
        if c.isdigit():
            j = i
            while j < n and expr[j].isdigit():
                j += 1
            # Check for decimal part
            if j < n and expr[j] == '.':
                # It's a float literal
                k = j + 1
                has_digit_after_dot = False
                while k < n and (expr[k].isdigit() or expr[k] == '.'):
                    if expr[k].isdigit():
                        has_digit_after_dot = True
                    k += 1
                if has_digit_after_dot:
                    tokens.append(_Token('FLOAT', float(expr[i:k]), i))
                    i = k
                    continue
                else:
                    # e.g., "2." - treat as float
                    tokens.append(_Token('FLOAT', float(expr[i:j]), i))
                    i = j
                    continue
            else:
                tokens.append(_Token('INT', int(expr[i:j]), i))
                i = j
                continue

        # Check for decimal literals starting with dot: .5, .50
        if c == '.':
            j = i + 1
            has_digit = False
            while j < n and (expr[j].isdigit() or expr[j] == '.'):
                if expr[j].isdigit():
                    has_digit = True
                j += 1
            if has_digit:
                tokens.append(_Token('FLOAT', float(expr[i:j]), i))
                i = j
                continue
            else:
                raise SyntaxError(f"Unexpected '.' at position {i}")

        # Identifier or keyword
        if c.isalpha() or c == '_':
            j = i
            while j < n and (expr[j].isalnum() or expr[j] == '_'):
                j += 1
            tokens.append(_Token('IDENT', expr[i:j], i))
            i = j
            continue

        # Operators and punctuation
        if c == '?':
            tokens.append(_Token('QUESTION', '?', i))
            i += 1
            continue

        if c == ':':
            tokens.append(_Token('COLON', ':', i))
            i += 1
            continue

        if c == '(':
            tokens.append(_Token('LPAREN', '(', i))
            i += 1
            continue

        if c == ')':
            tokens.append(_Token('RPAREN', ')', i))
            i += 1
            continue

        if c == '!':
            tokens.append(_Token('OP', '!', i))
            i += 1
            continue

        if c == '&' and i + 1 < n and expr[i + 1] == '&':
            tokens.append(_Token('OP', '&&', i))
            i += 2
            continue

        if c == '|' and i + 1 < n and expr[i + 1] == '|':
            tokens.append(_Token('OP', '||', i))
            i += 2
            continue

        if c == '=':
            # Check for ==
            if i + 1 < n and expr[i + 1] == '=':
                tokens.append(_Token('OP', '==', i))
                i += 2
                continue
            else:
                raise SyntaxError(f"Unexpected '=' at position {i}")

        if c == '<':
            if i + 1 < n and expr[i + 1] == '=':
                tokens.append(_Token('OP', '<=', i))
                i += 2
                continue
            else:
                tokens.append(_Token('OP', '<', i))
                i += 1
                continue

        if c == '>':
            if i + 1 < n and expr[i + 1] == '=':
                tokens.append(_Token('OP', '>=', i))
                i += 2
                continue
            else:
                tokens.append(_Token('OP', '>', i))
                i += 1
                continue

        if c == '+':
            tokens.append(_Token('OP', '+', i))
            i += 1
            continue

        if c == '-':
            tokens.append(_Token('OP', '-', i))
            i += 1
            continue

        if c == '*':
            tokens.append(_Token('OP', '*', i))
            i += 1
            continue

        if c == '/':
            tokens.append(_Token('OP', '/', i))
            i += 1
            continue

        if c == '%':
            tokens.append(_Token('OP', '%', i))
            i += 1
            continue

        if c == '^':
            tokens.append(_Token('OP', '^', i))
            i += 1
            continue

        raise SyntaxError(f"Unexpected character '{c}' at position {i}")

    tokens.append(_Token('EOF', None, n))
    return tokens


class _Parser:
    def __init__(self, tokens: list[_Token], env: dict[str, float]):
        self.tokens = tokens
        self.pos = 0
        self.env = env

    def current(self) -> _Token:
        return self.tokens[self.pos]

    def consume(self, kind: str = None, value: Union[str, int, float, None] = None) -> _Token:
        tok = self.current()
        if kind is not None and tok.kind != kind:
            raise SyntaxError(f"Expected {kind}, got {tok}")
        if value is not None and tok.value != value:
            raise SyntaxError(f"Expected '{value}', got '{tok.value}'")
        self.pos += 1
        return tok

    def parse_expression(self) -> Union[int, float]:
        """Parse the entire expression (lowest precedence: conditional)."""
        return self.parse_conditional()

    def parse_conditional(self) -> Union[int, float]:
        """Parse conditional expressions: a ? b : c (right-associative)."""
        left = self.parse_logical_or()

        if self.current().kind == 'QUESTION':
            self.consume('QUESTION')
            true_expr = self.parse_conditional()  # Right-associative
            self.consume('COLON')
            false_expr = self.parse_conditional()

            # Only evaluate the chosen branch
            if left != 0:
                return true_expr
            else:
                return false_expr

        return left

    def parse_logical_or(self) -> Union[int, float]:
        """Parse || and && (short-circuit)."""
        left = self.parse_logical_and()

        while self.current().kind == 'OP' and self.current().value == '||':
            self.consume('OP', '||')
            if left != 0:
                # Short-circuit: don't evaluate right side, but skip it syntactically
                self.skip_expression()
                left = 1
            else:
                right = self.parse_logical_and()
                left = 1 if right != 0 else 0

        return left

    def parse_logical_and(self) -> Union[int, float]:
        """Parse &&."""
        left = self.parse_comparison()

        while self.current().kind == 'OP' and self.current().value == '&&':
            self.consume('OP', '&&')
            if left != 0:
                right = self.parse_comparison()
                left = 1 if right != 0 else 0
            else:
                # Short-circuit: don't evaluate right side, but skip it syntactically
                self.skip_expression()
                left = 0

        return left

    def skip_expression(self):
        """Skip past an expression syntactically without evaluating it."""
        self.skip_conditional()

    def skip_conditional(self):
        left = self.skip_logical_or()
        if self.current().kind == 'QUESTION':
            self.consume('QUESTION')
            self.skip_conditional()  # Skip true branch
            self.consume('COLON')
            self.skip_conditional()  # Skip false branch

    def skip_logical_or(self):
        left = self.skip_logical_and()
        while self.current().kind == 'OP' and self.current().value == '||':
            self.consume('OP', '||')
            self.skip_logical_and()  # Skip right side

