        while self.current().kind == 'OP' and self.current().value in ('*', '/', '%'):
            self.consume('OP')
            self.skip_unary()  # Skip right side

    def skip_unary(self):
        if self.current().kind == 'OP' and self.current().value in ('-', '+', '!'):
            self.consume('OP')
            self.skip_unary()  # Skip operand
        else:
