    def parse_comparison(self) -> Union[int, float]:
        """Parse comparison operators: == != < <= > >= (non-associative)."""
        left = self.parse_addition()

        if self.current().kind == 'OP' and self.current().value in ('==', '!=', '<', '<=', '>', '>='):
            op = self.consume('OP').value

            # Check for chained comparisons (non-associative)
            if self.current().kind == 'OP' and self.current().value in ('==', '!=', '<', '<=', '>', '>='):
                raise SyntaxError("Chained comparisons are not allowed")

            right = self.parse_addition()

            if op == '==':
                left = 1 if left == right else 0
            elif op == '!=':
                left = 1 if left != right else 0
            elif op == '<':
                left = 1 if left < right else 0
            elif op == '<=':
                left = 1 if left <= right else 0
            elif op == '>':
                left = 1 if left > right else 0
            elif op == '>=':
                left = 1 if left >= right else 0

        return left

    def parse_addition(self) -> Union[int, float]:
        """Parse + and - (left-associative)."""
        left = self.parse_multiplication()

        while self.current().kind == 'OP' and self.current().value in ('+', '-'):
            op = self.consume('OP').value
            right = self.parse_multiplication()

            if op == '+':
                left = left + right
            else:
                left = left - right

        return left

    def parse_multiplication(self) -> Union[int, float]:
        """Parse *, /, % (left-associative)."""
        left = self.parse_unary()

        while self.current().kind == 'OP' and self.current().value in ('*', '/', '%'):
            op = self.consume('OP').value
            right = self.parse_unary()

            if op == '*':
                left = left * right
            elif op == '/':
                if right == 0:
                    raise ZeroDivisionError("division by zero")
                # / on two ints gives an int when it divides exactly, else a float
                if isinstance(left, int) and isinstance(right, int):
                    if left % right == 0:
                        left = left // right
                    else:
                        left = left / right
                else:
                    left = left / right
            elif op == '%':
                if right == 0:
                    raise ZeroDivisionError("modulo by zero")
                # Python semantics for %
                left = left % right

        return left

    def parse_unary(self) -> Union[int, float]:
        """Parse unary -, +, !."""
        if self.current().kind == 'OP' and self.current().value in ('-', '+', '!'):
            op = self.consume('OP').value
            operand = self.parse_unary()  # Unary operators are right-associative

            if op == '-':
                return -operand
            elif op == '+':
                return +operand
            elif op == '!':
                return 1 if operand == 0 else 0

