    def parse_power(self) -> Union[int, float]:
        """Parse power ^ (right-associative)."""
        base = self.parse_atom()

        if self.current().kind == 'OP' and self.current().value == '^':
            self.consume('OP', '^')
            exponent = self.parse_power()  # Right-associative

            result = base ** exponent
            return result

        return base

    def parse_atom(self) -> Union[int, float]:
        """Parse atoms: literals, identifiers, function calls, parentheses."""
        tok = self.current()

        if tok.kind == 'INT':
            self.consume('INT')
            return tok.value

        if tok.kind == 'FLOAT':
            self.consume('FLOAT')
            return tok.value

        if tok.kind == 'IDENT':
            name = tok.value
            self.consume('IDENT')

            # Check for function call
            if self.current().kind == 'LPAREN':
                return self.parse_function_call(name)

            # Lookup in env
            if name not in self.env:
                raise NameError(f"Unknown variable or function: '{name}'")

            val = self.env[name]
            return val

        if tok.kind == 'LPAREN':
            self.consume('LPAREN')
            result = self.parse_expression()
            self.consume('RPAREN')
            return result

        # Check for lone operators that should have been caught earlier
        if tok.kind == 'EOF':
            raise SyntaxError("Unexpected end of input")

        raise SyntaxError(f"Unexpected token: {tok}")

    def parse_function_call(self, name: str) -> Union[int, float]:
        """Parse function calls: min(...), max(...), abs(...)"""
        self.consume('LPAREN')

        # Parse arguments
        args = []
        if self.current().kind != 'RPAREN':
            args.append(self.parse_expression())
            while self.current().kind == 'OP' and self.current().value == ',':
                self.consume('OP', ',')
                args.append(self.parse_expression())

        self.consume('RPAREN')

        if name == 'min':
            if len(args) < 1:
                raise SyntaxError("min() requires at least 1 argument")
            return min(args)
        elif name == 'max':
            if len(args) < 1:
                raise SyntaxError("max() requires at least 1 argument")
            return max(args)
        elif name == 'abs':
            if len(args) != 1:
                raise SyntaxError("abs() requires exactly 1 argument")
            return abs(args[0])
        else:
            raise NameError(f"Unknown function: '{name}'")
