        self._iv = []
        for s, e in intervals:
            self.add(s, e)

    def add(self, start, end):
        if start >= end:
            return
        i = bisect.bisect_left(self._iv, (start,))
        # Check if we need to look back for overlapping interval
        j = i
        # Find the first interval that ends after 'start' (overlap candidate)
        while i > 0 and self._iv[i - 1][1] > start:
            i -= 1
        # Find the end of overlapping range
        while j < len(self._iv) and self._iv[j][0] < end:
            j += 1

        new_start = min(start, self._iv[i][0] if i < len(self._iv) else start)
        new_end = max(end, self._iv[j - 1][1] if j > i and j <= len(self._iv) else end)

        # But we need to be careful: the intervals from i to j-1 are being merged.
        # Let's recompute properly.
        new_start = start
        new_end = end
        for k in range(i, j):
            new_start = min(new_start, self._iv[k][0])
            new_end = max(new_end, self._iv[k][1])

        self._iv[i:j] = [(new_start, new_end)]

    def remove(self, start, end):
        if start >= end:
            return
        out = []
        for s, e in self._iv:
            if e <= start or s >= end:
                # No overlap
                out.append((s, e))
            else:
                # There is overlap. Split the interval.
                if s < start:
                    out.append((s, start))
                if e > end:
                    out.append((end, e))
        self._iv = out

    def contains(self, x):
        i = bisect.bisect_left(self._iv, (x,))
        # Check interval at index i and possibly i-1
        if i < len(self._iv) and self._iv[i][0] <= x < self._iv[i][1]:
            return True
        if i > 0 and self._iv[i - 1][0] <= x < self._iv[i - 1][1]:
            return True
        return False

    def free(self, lo, hi):
        gaps = []
        cur = lo
        for s, e in self._iv:
            if s > cur:
                # There is a gap between cur and s
                if cur < s:
                    gaps.append((cur, min(s, hi)))
            cur = max(cur, e)
            if cur >= hi:
                break
        if cur < hi:
            gaps.append((cur, hi))
        return gaps

    def __iter__(self):
        return iter(self._iv)

    def __len__(self):
        return len(self._iv)
