import bisect


class IntervalSet:
    def __init__(self, intervals=()):
        self._iv = []
        for s, e in intervals:
            self.add(s, e)

    def add(self, start, end):
        if start >= end:
            return
        # Find the range of existing intervals that overlap with [start, end)
        # An interval [s, e) overlaps with [start, end) if s < end and e > start

        # i: first index where interval could overlap (interval's end > start)
        # We can use bisect to find candidates.
        # Intervals are sorted by start. 
        # Any interval that starts before 'end' might overlap.

        # Find the leftmost interval that ends after 'start'
        # Since intervals are sorted by start, we can binary search for 'start' in terms of start values.

        i = bisect.bisect_left(self._iv, (start,))
        # Check if there's an overlap with interval at i-1
        if i > 0 and self._iv[i - 1][1] > start:
            i -= 1

        # Now find j: first index where interval starts >= end
        j = bisect.bisect_left(self._iv, (end,))

        # Merge intervals from i to j-1
        new_start = min(start, self._iv[k][0] for k in range(i, j) if k < len(self._iv)) if i < j else start
        new_end = max(end, self._iv[k][1] for k in range(i, j) if k < len(self._iv)) if i < j else end

        # But wait, we need to consider all intervals from i to j-1. Let's be more careful.
        # The intervals to merge are those from index i to j-1 (inclusive).
        if i < j:
            new_start = min(start, min(iv[0] for iv in self._iv[i:j]))
            new_end = max(end, max(iv[1] for iv in self._iv[i:j]))
        else:
            new_start = start
            new_end = end

        self._iv[i:j] = [(new_start, new_end)]

    def remove(self, start, end):
        if start >= end:
            return
        out = []
        for s, e in self._iv:
            if e <= start or s >= end:
                # No overlap
                out.append((s, e))
            else:
                # There is overlap. Split the interval.
                if s < start:
                    out.append((s, start))
                if e > end:
                    out.append((end, e))
        self._iv = out

    def contains(self, x):
        i = bisect.bisect_left(self._iv, (x,))
        # Check interval at index i and possibly i-1
        if i < len(self._iv) and self._iv[i][0] <= x < self._iv[i][1]:
            return True
        if i > 0 and self._iv[i - 1][0] <= x < self._iv[i - 1][1]:
            return True
        return False

    def free(self, lo, hi):
        gaps = []
        cur = lo
        for s, e in self._iv:
            if s > cur:
                # There is a gap between cur and s
                end_gap = min(s, hi)
                if cur < end_gap:
                    gaps.append((cur, end_gap))
            cur = max(cur, e)
            if cur >= hi:
                break
        if cur < hi:
            gaps.append((cur, hi))
        return gaps

    def __iter__(self):
        return iter(self._iv)

    def __len__(self):
        return len(self._iv)
