import heapq
from collections import defaultdict
from typing import Optional


def route(grid: list[str]) -> tuple[int, str] | None:
    """
    Find the cheapest path from S to E in a grid with walls, variable costs, and teleport pads.

    Args:
        grid: List of strings representing the grid.

    Returns:
        A tuple (total_cost, moves) for the cheapest path where moves is lexicographically smallest,
        or None if E is unreachable.

    Raises:
        ValueError: For malformed grids.
    """
    # Validate the grid
    if not grid or not isinstance(grid, list):
        raise ValueError("Grid must be a non-empty list of strings")

    row_len = len(grid[0])
    if row_len == 0:
        raise ValueError("Rows must have non-zero length")

    for i, row in enumerate(grid):
        if not isinstance(row, str):
            raise ValueError(f"Row {i} is not a string")
        if len(row) != row_len:
            raise ValueError(f"Ragged rows: row {i} has length {len(row)}, expected {row_len}")

    start = None
    end = None
    pad_positions = defaultdict(list)  # letter -> list of (r, c)

    for r in range(len(grid)):
        for c in range(len(grid[0])):
            ch = grid[r][c]
            if ch == 'S':
                if start is not None:
                    raise ValueError("Multiple S found")
                start = (r, c)
            elif ch == 'E':
                if end is not None:
                    raise ValueError("Multiple E found")
                end = (r, c)
            elif ch == '#':
                pass  # wall
            elif ch == '.':
                pass  # cost 1
            elif ch.isdigit() and '1' <= ch <= '9':
                pass  # cost int(ch)
            elif ch.islower():
                pad_positions[ch].append((r, c))
            else:
                raise ValueError(f"Unknown character '{ch}' at ({r}, {c})")

    if start is None:
        raise ValueError("No S found")
    if end is None:
        raise ValueError("No E found")

    # Validate pad positions: each letter must appear exactly 0 or 2 times
    for letter, positions in pad_positions.items():
        if len(positions) != 2:
            raise ValueError(f"Letter '{letter}' appears {len(positions)} times, expected 0 or 2")

    # Directions ordered lexicographically: D < L < R < T < U
    # For regular moves: D=(1,0), L=(0,-1), R=(0,1), U=(-1,0)
    # T is teleport which depends on position

    dirs = [
        ('D', 1, 0),
        ('L', 0, -1),
        ('R', 0, 1),
        ('U', -1, 0),
    ]

    def get_cell_cost(r: int, c: int) -> int:
        ch = grid[r][c]
        if ch == 'S' or ch == 'E':
            return 1
        elif ch == '#':
            raise ValueError("Should not move into a wall")
        elif ch == '.':
            return 1
        elif ch.isdigit():
            return int(ch)
        elif ch.islower():
            return 1
        else:
            raise ValueError(f"Unknown character '{ch}' at ({r}, {c})")

    # State: (cost, path_length, r, c, moves_str)
    # But storing full strings in heap is expensive. Instead, we use Dijkstra with (cost, moves_tuple)
    # where moves_tuple is a tuple of move characters. We want lexicographically smallest moves string.

    # Since grids are up to 60x60, and costs can vary, we need an efficient approach.
    # Key insight: For same cost, we want lexicographically smallest path. 
    # We can use Dijkstra where the priority is (cost, path_as_tuple_of_moves).

    # To avoid storing huge strings, we can store the path as a tuple of moves.
    # But this could be memory intensive. Let's think differently.

    # Alternative: Since we want lexicographically smallest among cheapest, and Dijkstra explores by cost,
    # when we first reach E with a certain cost, there might be multiple paths with same cost.
    # We need to ensure we get the lex smallest.

    # Standard approach: Use (cost, path_tuple) as priority in heap.
    # To optimize, note that for a given cell, once we pop it from the heap with some cost and path,
    # any future arrival at that cell with higher cost is worse. With same cost, if the new path is lex larger, it's also worse.
    # But if same cost and lex smaller... that shouldn't happen if we process correctly.

    # Actually, for Dijkstra with (cost, path_lex), when we visit a node:
    # - If we've already visited with lower cost, skip.
    # - If same cost but lex larger path, skip.
    # - If same cost and lex equal or smaller... but since we use heap, the first time we pop a state for (r,c) 
    #   should have the minimal (cost, lex_path). 

    # Let's track best known for each cell: (best_cost, best_path_tuple)

    from collections import defaultdict

    # best[(r,c)] = (min_cost, min_path_tuple)
    best = {}

    start_r, start_c = start
    end_r, end_c = end

    # Initial state: at start, cost 0, empty path
    # When we move INTO a cell, we pay that cell's cost. Starting at S doesn't incur cost yet? 
    # Wait, re-reading: "Moving into a cell costs that cell's cost". So starting at S, no move has been made, cost is 0.
    # First move into a neighbor incurs that neighbor's cost.

    heap = [(0, (), start_r, start_c)]
    best[(start_r, start_c)] = (0, ())

    while heap:
        cost, path_tuple, r, c = heapq.heappop(heap)

        # Check if this state is outdated
        if (r, c) in best:
            prev_cost, prev_path = best[(r, c)]
            if cost > prev_cost:
                continue
            if cost == prev_cost and path_tuple > prev_path:
                continue

        # If we reached the end
        if (r, c) == (end_r, end_c):
            moves_str = ''.join(path_tuple)
            return (cost, moves_str)

        # Try all moves: D, L, R, U, and T if on a pad

        # Regular moves
        for move_char, dr, dc in dirs:
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                ch = grid[nr][nc]
                if ch == '#':
                    continue
                cell_cost = get_cell_cost(nr, nc)
                new_cost = cost + cell_cost
                new_path = path_tuple + (move_char,)

                # Check if this is better
                if (nr, nc) not in best:
                    best[(nr, nc)] = (new_cost, new_path)
                    heapq.heappush(heap, (new_cost, new_path, nr, nc))
                else:
                    prev_cost, prev_path = best[(nr, nc)]
                    if new_cost < prev_cost or (new_cost == prev_cost and new_path < prev_path):
                        best[(nr, nc)] = (new_cost, new_path)
                        heapq.heappush(heap, (new_cost, new_path, nr, nc))

        # Teleport move T: if current cell is a pad
        ch = grid[r][c]
        if ch.islower() and len(pad_positions[ch]) == 2:
            # Find the other position
            positions = pad_positions[ch]
            other_r, other_c = None, None
            for pr, pc in positions:
                if (pr, pc) != (r, c):
                    other_r, other_c = pr, pc
                    break

            if other_r is not None:
                # Check that the destination is not a wall
                dest_ch = grid[other_r][other_c]
                if dest_ch != '#':
                    cell_cost = get_cell_cost(other_r, other_c)
                    new_cost = cost + 2 + cell_cost
                    new_path = path_tuple + ('T',)

                    if (other_r, other_c) not in best:
                        best[(other_r, other_c)] = (new_cost, new_path)
                        heapq.heappush(heap, (new_cost, new_path, other_r, other_c))
                    else:
                        prev_cost, prev_path = best[(other_r, other_c)]
                        if new_cost < prev_cost or (new_cost == prev_cost and new_path < prev_path):
                            best[(other_r, other_c)] = (new_cost, new_path)
                            heapq.heappush(heap, (new_cost, new_path, other_r, other_c))

    return None
