import re
from typing import List, Optional, Tuple


class Version:
    """Represents a SemVer 2.0.0 version."""

    def __init__(self, major: int, minor: int, patch: int, prerelease: Optional[str] = None, build: Optional[str] = None):
        self.major = major
        self.minor = minor
        self.patch = patch
        self.prerelease = prerelease
        self.build = build

    def __repr__(self):
        s = f"Version({self.major}, {self.minor}, {self.patch}"
        if self.prerelease is not None:
            s += f", prerelease={self.prerelease!r}"
        if self.build is not None:
            s += f", build={self.build!r}"
        s += ")"
        return s

    def __eq__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        # Equality follows precedence: compare major, minor, patch, prerelease (build ignored)
        return self._cmp_key() == other._cmp_key()

    def __hash__(self):
        return hash(self._cmp_key())

    def _cmp_key(self):
        """Key for comparison: (major, minor, patch, is_prerelease_flag, prerelease_tuple_or_None)"""
        # Prerelease versions are less than release versions.
        # For sorting/comparison: if no prerelease, it's considered "greater" than any prerelease of the same MAJOR.MINOR.PATCH.
        # We use a tuple that allows proper ordering.
        if self.prerelease is None:
            pre_flag = 1  # release
            pre_tuple = ()
        else:
            pre_flag = 0  # prerelease
            pre_tuple = self._parse_prerelease(self.prerelease)
        return (self.major, self.minor, self.patch, pre_flag, pre_tuple)

    @staticmethod
    def _parse_prerelease(pre_str: str):
        """Parse a prerelease string into a tuple of identifiers for comparison."""
        if not pre_str:
            return ()
        identifiers = pre_str.split('.')
        result = []
        for ident in identifiers:
            # Each identifier is either numeric or alphanumeric.
            # Numeric identifiers are compared as integers.
            # Alphanumeric identifiers are compared lexically.
            # Numeric < Alphanumeric.
            if ident.isdigit():
                result.append((0, int(ident), ''))  # (type, num, str) type 0 for numeric
            else:
                result.append((1, 0, ident))  # type 1 for alphanumeric
        return tuple(result)

    def __lt__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._cmp_key() < other._cmp_key()

    def __le__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._cmp_key() <= other._cmp_key()

    def __gt__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._cmp_key() > other._cmp_key()

    def __ge__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._cmp_key() >= other._cmp_key()


def parse(v: str) -> Version:
    """Parse a SemVer 2.0.0 version string."""
    v = v.strip()
    # Remove leading 'v' or '='
    if v.startswith('v') or v.startswith('='):
        v = v[1:]

    # SemVer regex pattern
    # MAJOR.MINOR.PATCH[-PRERELEASE][+BUILD]
    # No leading zeros in numeric parts
    pattern = r'^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-((?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?(?:\+([0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*))?$'

    match = re.match(pattern, v)
    if not match:
        raise ValueError(f"Invalid version string: {v!r}")

