                comparators.append(('>=', Version(version.major, version.minor, 0), False))
            else:
                comparators.append((op, version, is_x))

            i += 1

    return comparators


def _parse_comparator(token: str) -> Tuple[str, str]:
    """Parse a single comparator token into (operator, version_string)."""
    token = token.strip()

    if not token:
        raise ValueError(f"Empty comparator")

    pattern = r'^(>=|<=|>|<|=)?(.+)$'
    match = re.match(pattern, token)
    if not match:
        raise ValueError(f"Invalid comparator: {token!r}")

    op = match.group(1) or ''
    version_str = match.group(2).strip()

    if not version_str:
        raise ValueError(f"Invalid comparator: {token!r}")

    return op, version_str


def satisfies(version_str: str, rng_str: str) -> bool:
    """Check if a version satisfies a range."""
    version = parse(version_str)
    sets = parse_range(rng_str)

    for comparators in sets:
        if _version_satisfies_set(version, comparators):
            return True

    return False


def max_satisfying(versions: List[str], rng_str: str) -> Optional[str]:
    """Find the maximum version that satisfies the range."""
    satisfying = []

    for v_str in versions:
        try:
            version = parse(v_str)
            if satisfies(version_str=v_str, rng_str=rng_str):
                satisfying.append((version, v_str))
        except ValueError:
            continue

    if not satisfying:
        return None

    satisfying.sort(key=lambda x: x[0], reverse=True)

    return satisfying[0][1]
