def split_command(line: str, env: dict[str, str]) -> list[str]:
    """
    Implement a subset of POSIX shell word splitting and parameter expansion.

    Args:
        line: The command line string to parse.
        env: A dictionary representing the environment variables.

    Returns:
        A list of words after parsing, splitting, and expansion.

    Raises:
        ValueError: For unterminated quotes, unterminated ${}, or trailing backslash.
    """
    return _parse_and_expand(line, env)


def _expand_var(line: str, pos: int, env: dict[str, str]) -> dict:
    """
    Expand a variable starting at position pos in line (pos points to the character after $).
    Returns {'text': expanded_value, 'next_index': index after expansion}.
    """
    if pos >= len(line):
        return {'text': '$', 'next_index': pos}

    c = line[pos]

    if c == '{':
        end = _find_matching_brace(line, pos)
        if end is None:
            raise ValueError("Unterminated ${")

        inner = line[pos + 1:end]
        next_index = end + 1

        result = _expand_braced(inner, env)
        return {'text': result, 'next_index': next_index}

    elif c.isalpha() or c == '_':
        start = pos
        while pos < len(line) and (line[pos].isalnum() or line[pos] == '_'):
            pos += 1
        name = line[start:pos]

        value = env.get(name, '')
        return {'text': value, 'next_index': pos}

    else:
        return {'text': '$', 'next_index': pos + 1}


def _find_matching_brace(line: str, open_pos: int) -> int | None:
    """Find the matching } for { at open_pos. Returns index of } or None."""
    depth = 1
    i = open_pos + 1
    while i < len(line):
        if line[i] == '{':
            depth += 1
        elif line[i] == '}':
            depth -= 1
            if depth == 0:
                return i
        i += 1
    return None


def _expand_braced(inner: str, env: dict[str, str]) -> str:
    """
    Expand ${inner} where inner is the content between { and }.
    Supports NAME, NAME:-default, NAME-default forms.
    """
    match = _match_var_name(inner)
    if not match:
        return ''

    name, rest = match

    if not rest:
        return env.get(name, '')

    if rest.startswith(':-'):
        default_text = rest[2:]
        value = env.get(name, '')
        if value == '':
            expanded_default = _expand_all(default_text, env)
            return expanded_default
        else:
            return value
    elif rest.startswith('-'):
        default_text = rest[1:]
        value = env.get(name, '')
        if value == '':
            expanded_default = _expand_all(default_text, env)
            return expanded_default
        else:
            return value

    return env.get(name, '')


def _match_var_name(s: str) -> tuple[str, str] | None:
    """Match a variable name [A-Za-z_][A-Za-z0-9_]* from start of s."""
    if not s or not (s[0].isalpha() or s[0] == '_'):
        return None

    i = 1
    while i < len(s) and (s[i].isalnum() or s[i] == '_'):
        i += 1

    name = s[:i]
    rest = s[i:]

    if rest and not rest.startswith(':') and not rest.startswith('-'):
        return None

    return (name, rest)


def _expand_all(text: str, env: dict[str, str]) -> str:
    """Expand all $ variables in the given text."""
    result = []
    i = 0
    n = len(text)

    while i < n:
        if text[i] == '$':
            expanded = _expand_var(text, i, env)
            result.append(expanded['text'])
            i = expanded['next_index']
        else:
            result.append(text[i])
            i += 1

    return ''.join(result)


def _parse_and_expand(line: str, env: dict[str, str]) -> list[str]:
    """Parse the line and produce final words."""
    words = []

    i = 0
    n = len(line)

    while i < n:
        # Skip leading whitespace
        while i < n and line[i] in (' ', '\t', '\n'):
            i += 1

        if i >= n:
            break

        # Parse a single word
        word_parts = []

        while i < n and line[i] not in (' ', '\t', '\n'):
            c = line[i]

            if c == "'":
                # Single quoted string
                i += 1
                start = i
                while i < n and line[i] != "'":
                    i += 1
                if i >= n:
                    raise ValueError("Unterminated single quote")
                text = line[start:i]
                word_parts.append((True, text))
                i += 1  # skip closing quote

            elif c == '"':
                # Double quoted string
                i += 1
                result_chars = []
                while i < n and line[i] != '"':
                    c2 = line[i]
                    if c2 == '\\' and i + 1 < n:
                        next_c = line[i + 1]
                        if next_c in ('$', '"', '\\', '\n'):
                            result_chars.append(next_c)
                            i += 2
                        else:
                            result_chars.append('\\')
                            result_chars.append(next_c)
                            i += 2
                    elif c2 == '$':
                        expanded = _expand_var(line, i + 1, env)
                        result_chars.append(expanded['text'])
                        i = expanded['next_index']
                    else:
                        result_chars.append(c2)
                        i += 1
                if i >= n:
                    raise ValueError("Unterminated double quote")
                text = ''.join(result_chars)
                word_parts.append((True, text))
                i += 1  # skip closing quote

            elif c == '\\':
                if i + 1 >= n:
                    raise ValueError("Trailing unescaped backslash")
                next_c = line[i + 1]
                if next_c == '\n':
                    # Backslash-newline removed entirely
                    i += 2
                else:
                    word_parts.append((False, next_c))
                    i += 2

            elif c == '$':
                expanded = _expand_var(line, i + 1, env)
                word_parts.append((False, expanded['text']))
                i = expanded['next_index']

            else:
                word_parts.append((False, c))
                i += 1

        # Process the collected word parts into final words (handling field splitting)
        final_word_list = _process_word(word_parts, env)
        words.extend(final_word_list)

    return words


def _process_word(parts: list[tuple[bool, str]], env: dict[str, str]) -> list[str]:
    """
    Process word parts into final words.
    - Join all parts into a single string.
    - If the entire word is from unquoted expansions, perform field splitting.
    - If the result of an entirely unquoted expansion is empty, remove it (unless it's "" or '').
    """
    # Check if all parts are quoted
    all_quoted = all(is_q for is_q, _ in parts)

    # Join all parts into one string
    joined = ''.join(text for _, text in parts)

    if all_quoted:
        # No field splitting on quoted content
        return [joined]

    # For unquoted words, perform field splitting
    if not joined:
        # Check if this came from empty quoted strings (like "" or '')
        # If all parts were quoted and empty, we should keep the empty word
        if all(is_q and text == '' for is_q, text in parts):
            return ['']
        else:
            # Empty word from unquoted expansion - remove it
            return []

    # Split on whitespace (spaces, tabs, newlines)
    split_words = joined.split()
    return split_words


# Keep the old functions for compatibility with _expand_var calls
_find_matching_brace = _find_matching_brace
_expand_braced = _expand_braced
_match_var_name = _match_var_name
_expand_all = _expand_all
