from __future__ import annotations

import dataclasses
import typing
from typing import Any, get_type_hints, Optional, Union, List, Dict, Tuple, Literal

# Define LoadError
class LoadError(ValueError):
    """Exception raised when loading a dataclass from JSON-like data fails."""
    def __init__(self, path: str, message: str = ""):
        self.path = path
        if message:
            super().__init__(f"{path}: {message}")
        else:
            super().__init__(path)

def _resolve_type(hints: dict[str, Any], annotation: Any) -> Any:
    """Resolve a type annotation using get_type_hints. If the annotation is a string, it's already resolved by get_type_hints."""
    return annotation

def _get_origin_and_args(tp: Any):
    """Get the origin and args of a generic type."""
    origin = getattr(tp, '__origin__', None)
    args = getattr(tp, '__args__', ())
    return origin, args

def is_union_type(tp: Any) -> bool:
    """Check if tp is a Union type (including | syntax)."""
    origin, _ = _get_origin_and_args(tp)
    return origin is Union

def get_union_members(tp: Any) -> tuple:
    """Get the members of a Union type."""
    _, args = _get_origin_and_args(tp)
    return args

def is_optional_type(tp: Any) -> bool:
    """Check if tp is Optional[T] (which is Union[T, None])."""
    origin, args = _get_origin_and_args(tp)
    if origin is Union:
        non_none_args = [a for a in args if a is not type(None)]
        return len(non_none_args) == 1 and type(None) in args
    return False

def get_optional_type(tp: Any) -> Any:
    """Get the T from Optional[T]."""
    _, args = _get_origin_and_args(tp)
    non_none_args = [a for a in args if a is not type(None)]
    if len(non_none_args) == 1:
        return non_none_args[0]
    raise ValueError("Not an Optional type")

def is_literal_type(tp: Any) -> bool:
    """Check if tp is a Literal type."""
    origin, _ = _get_origin_and_args(tp)
    return origin is Literal

def get_literal_values(tp: Any) -> tuple:
    """Get the values from a Literal type."""
    _, args = _get_origin_and_args(tp)
    return args

def is_list_type(tp: Any) -> bool:
    """Check if tp is a list[T] type."""
    origin, _ = _get_origin_and_args(tp)
    return origin is list

def get_list_item_type(tp: Any) -> Any:
    """Get the item type T from list[T]."""
    _, args = _get_origin_and_args(tp)
    if args:
        return args[0]
    raise ValueError("list without item type")

def is_dict_type(tp: Any) -> bool:
    """Check if tp is a dict[str, T] type."""
    origin, _ = _get_origin_and_args(tp)
    return origin is dict

def get_dict_key_type(tp: Any) -> Any:
    """Get the key type from dict[K, V]."""
    _, args = _get_origin_and_args(tp)
    if len(args) >= 1:
        return args[0]
    raise ValueError("dict without key type")

def get_dict_value_type(tp: Any) -> Any:
    """Get the value type from dict[K, V]."""
    _, args = _get_origin_and_args(tp)
    if len(args) >= 2:
        return args[1]
    raise ValueError("dict without value type")

def is_tuple_type(tp: Any) -> bool:
    """Check if tp is a tuple type."""
    origin, _ = _get_origin_and_args(tp)
    return origin is tuple

def get_tuple_types(tp: Any) -> tuple:
    """Get the types from a tuple type. For tuple[T, ...], returns (T, Ellipsis)."""
    _, args = _get_origin_and_args(tp)
    return args

def is_dataclass_type(tp: Any) -> bool:
    """Check if tp is a dataclass type."""
    return dataclasses.is_dataclass(tp) and not isinstance(tp, type) or (isinstance(tp, type) and dataclasses.is_dataclass(tp))

def _load_value(tp: Any, value: Any, path: str, hints: dict[str, Any]) -> Any:
    """Load a value according to the given type annotation."""

    # Check for None/NoneType
    if tp is type(None):
        if value is None:
            return None
        else:
            raise LoadError(path, f"Expected None but got {type(value).__name__}")

    # Check for Literal types
    if is_literal_type(tp):
        literal_values = get_literal_values(tp)
        # In Literal, the value must match one of the literals exactly.
        # Also, the type should match (though in Python, int 1 == True is True, but we need strict equality).
        for lv in literal_values:
            if value == lv and type(value) == type(lv):
                return lv
        raise LoadError(path, f"Value {value!r} not in Literal{literal_values}")

    # Check for Union types (including Optional)
    if is_union_type(tp):
        members = get_union_members(tp)
        # Try each member left to right
        errors = []
        for member in members:
            try:
                return _load_value(member, value, path, hints)
            except LoadError as e:
                errors.append(e)

        # If None is one of the members and value is None, it should have succeeded.
        # But if we get here, none of the members matched.
        # For Optional[T], if value is not None, we report the error from loading T.
        # The errors list contains LoadErrors from each member.
        # We need to decide which error to raise.
        # If one of the members is NoneType and value is None, it should have worked.
        # So if we're here, either value is not None and no non-None member matched, or value is None but something weird happened.

        # For Union types, if none of the members succeeded, raise an error.
        # Prefer the error from the first non-NoneType member if value is not None? 
        # The spec says: "For T | None with non-null data, report the error from loading T".
        # So if value is not None, we should look for errors from non-None members.

        if value is not None:
            # Find errors from non-None members
            non_none_errors = []
            for member, err in zip(members, errors):
                if member is not type(None):
                    non_none_errors.append(err)
            if non_none_errors:
                # Raise the first error from a non-None member
                raise non_none_errors[0]

        # If value is None and we're here, it means NoneType wasn't in the union or something else went wrong.
        # Just raise the first error.
        if errors:
            raise errors[0]

        raise LoadError(path, f"Value {value!r} does not match any member of Union{members}")

    # Check for dataclass types
    if is_dataclass_type(tp):
        return _load_dataclass(tp, value, path, hints)

    # Check for list types
    if is_list_type(tp):
        if not isinstance(value, list):
            raise LoadError(path, f"Expected list but got {type(value).__name__}")
        item_tp = get_list_item_type(tp)
        result = []
        for i, item in enumerate(value):
            item_path = f"{path}[{i}]"
            result.append(_load_value(item_tp, item, item_path, hints))
        return result

    # Check for dict types
    if is_dict_type(tp):
        if not isinstance(value, dict):
            raise LoadError(path, f"Expected dict but got {type(value).__name__}")
        key_tp = get_dict_key_type(tp)
        value_tp = get_dict_value_type(tp)
        result = {}
        for k, v in value.items():
            # Keys must be strings according to the spec (dict[str, T])
            if not isinstance(k, str):
                raise LoadError(path, f"Dict key {k!r} is not a string")
            item_path = f"{path}.{k}"
            result[k] = _load_value(value_tp, v, item_path, hints)
        return result

    # Check for tuple types
    if is_tuple_type(tp):
        if not isinstance(value, list):
            raise LoadError(path, f"Expected list for tuple but got {type(value).__name__}")
        tuple_types = get_tuple_types(tp)

        # Check for variable-length tuple (tuple[T, ...])
        if len(tuple_types) == 2 and tuple_types[1] is Ellipsis:
            item_tp = tuple_types[0]
            result = []
            for i, item in enumerate(value):
                item_path = f"{path}[{i}]"
                result.append(_load_value(item_tp, item, item_path, hints))
            return tuple(result)

        # Fixed-length tuple
        expected_len = len(tuple_types)
        if len(value) != expected_len:
            raise LoadError(path, f"Expected tuple of length {expected_len} but got {len(value)}")

        result = []
        for i, (tp_item, val_item) in enumerate(zip(tuple_types, value)):
            item_path = f"{path}[{i}]"
            result.append(_load_value(tp_item, val_item, item_path, hints))
        return tuple(result)

    # Primitive types
    if tp is int:
        # bool is not accepted for int
        if isinstance(value, bool):
            raise LoadError(path, f"Expected int but got bool")
        if not isinstance(value, int):
            raise LoadError(path, f"Expected int but got {type(value).__name__}")
        return value

    if tp is float:
        # bool is not accepted for float
        if isinstance(value, bool):
            raise LoadError(path, f"Expected float but got bool")
        if isinstance(value, int):
            return float(value)
        if not isinstance(value, float):
            raise LoadError(path, f"Expected float but got {type(value).__name__}")
        return value

    if tp is str:
        if not isinstance(value, str):
            raise LoadError(path, f"Expected str but got {type(value).__name__}")
        return value

    if tp is bool:
        if not isinstance(value, bool):
            raise LoadError(path, f"Expected bool but got {type(value).__name__}")
        return value

    # If we get here, we don't know how to handle the type
    raise LoadError(path, f"Unsupported type {tp}")

def _load_dataclass(cls: Any, data: Any, path: str, hints: dict[str, Any]) -> Any:
    """Load a dataclass instance from data."""
    if not isinstance(data, dict):
        raise LoadError(path, f"Expected dict for dataclass {cls.__name__} but got {type(data).__name__}")

    # Get field info
    fields = dataclasses.fields(cls)
    field_map = {f.name: f for f in fields}

    # Check for unknown keys
    for key in data:
        if key not in field_map:
            raise LoadError(f"{path}.{key}", f"Unknown key '{key}'")

    # Build instance
    init_kwargs = {}
    for field in fields:
        name = field.name
        if name in data:
            # Load the value
            field_tp = hints.get(name, field.type)
            try:
                loaded_value = _load_value(field_tp, data[name], f"{path}.{name}", hints)
            except LoadError as e:
                raise e
            init_kwargs[name] = loaded_value
        else:
            # Check for default or default_factory
            if field.default is not dataclasses.MISSING:
                init_kwargs[name] = field.default
            elif field.default_factory is not dataclasses.MISSING:
                init_kwargs[name] = field.default_factory()
            else:
                raise LoadError(f"{path}.{name}", f"Missing required field '{name}'")

    return cls(**init_kwargs)

def load(cls, data):
    """Build an instance of a dataclass type from JSON-like data."""
    # Resolve type hints
    try:
        hints = get_type_hints(cls)
    except Exception as e:
        # If get_type_hints fails, we might still have field annotations
        hints = {}

    path = "$"
    return _load_value(cls, data, path, hints)
