#!/usr/bin/env bash
set -euo pipefail

# Defaults
DELIM=","
SUM_MODE=0
COLUMN=""
FILE=""

# Parse arguments
while getopts "ds" opt; do
    case "$opt" in
        d) DELIM="$OPTARG" ;;
        s) SUM_MODE=1 ;;
        *) exit 1 ;;
    esac
done
shift $((OPTIND - 1))

if [[ $# -lt 1 ]]; then
    echo "Usage: $0 [-d DELIM] [-s] COLUMN [FILE]" >&2
    exit 1
fi

COLUMN="$1"
if [[ $# -ge 2 ]]; then
    FILE="$2"
fi

# Read input into a variable or process file
INPUT_CMD="cat"
if [[ -n "$FILE" ]]; then
    if [[ ! -f "$FILE" ]]; then
        echo "Error: File not found: $FILE" >&2
        exit 1
    fi
    INPUT_CMD="cat '$FILE'"
fi

# We will use awk to parse the CSV properly because bash string manipulation is too fragile for RFC 4180
# with quoted fields containing delimiters, newlines, and escaped quotes.

awk -v delim="$DELIM" -v col_spec="$COLUMN" -v sum_mode="$SUM_MODE" '
BEGIN {
    FS = "" # We will handle field splitting manually to respect quotes
    col_index = -1
    header_done = 0
    row_count = 0
    in_quote = 0
    current_field = ""
    current_row_fields = ""

    # Initialize counters for sum mode
    count = 0
    sum_val = 0
    min_val = ""
    max_val = ""
}

# Function to parse a single CSV record from the buffer
# Since awk processes line by line, we need to handle multi-line quoted fields.
# We will accumulate lines until a full record is formed.

{
    # Append current line to our accumulator with a newline separator if needed
    # But we need to be careful about how we reconstruct.
    # Actually, let us process the entire input as a stream of characters? 
    # No, awk line-by-line is standard. We maintain state for an incomplete record.

    line = $0

    # If we are in the middle of a quoted field (multi-line), append this line to current_field
    if (in_quote) {
        current_field = current_field "\n" line
        # Check if this line ends with an even number of quotes (closing the quote)
        # We need to count trailing unescaped quotes.
        # A simpler heuristic: check if the last character is a quote and we are inside one.
        # Actually, let us just look at the end of the string for unbalanced quotes.
        # But since we append newlines, we need to track carefully.

        # Let us count quotes from the end.
        temp = current_field
        num_quotes = 0
        while (match(temp, /"$/)) {
            num_quotes++
            temp = substr(temp, 1, RSTART - 1)
        }
        if (num_quotes % 2 == 1) {
            # Still in quote
            next
        } else {
            # Quote closed
            in_quote = 0
            # Now current_field is complete for this field.
            # But we might have more fields on this line after the closing quote?
            # No, if we are reconstructing a record that was split across lines,
            # the rest of the record follows on subsequent lines until the final newline.
            # However, standard CSV parsing usually implies that the closing quote is followed by 
            # delimiter or end-of-record. If it was multi-line, the newlines were part of the field.
            # The line we just read might contain more fields? 
            # Actually, if a field contains a newline, the record continues on the next line.
            # So the "next" lines are part of the SAME record until the record is complete.

            # Let us change strategy: accumulate the whole record in `record_buf`.
            # When a record is complete (balanced quotes), process it.
        }
    } else {
        # New record start or continuation?
        # If we were not in_quote, this line starts a new potential record.
        # But wait, if the previous record ended, we processed it.

        # Check if this line itself contains an unclosed quote.
        temp = line
        num_quotes = 0
        while (match(temp, /"$/)) {
            num_quotes++
            temp = substr(temp, 1, RSTART - 1)
        }

        if (num_quotes % 2 == 1) {
            # Start of a multi-line quoted field
            in_quote = 1
            current_field = line
            next
        } else {
            # Complete record on this line (or empty line?)
            # Process `line` as a complete record.
            process_record(line)
        }
    }
}

END {
    if (in_quote) {
        print "Error: Unterminated quote at end of input" > "/dev/stderr"
        exit 4
    }

    if (col_index == -1 && header_done == 0) {
        # This implies no header was found or column not found?
        # If file is empty, col_index remains -1.
        if (length(col_spec) > 0) {
            print "Error: Unknown column: " col_spec > "/dev/stderr"
            exit 3
        }
    }

    if (sum_mode) {
        if (count == 0) {
            print "count=0"
        } else {
            printf "count=%d sum=%g min=%g max=%g\n", count, sum_val, min_val, max_val
        }
    }
}

function process_record(rec,    n, fields, i, c, in_q, field, len) {
    # Parse `rec` into fields respecting quotes and delimiter.
