    trimmed_line = trim(line)

    # Skip blank lines
    if (trimmed_line == "") {
        next
    }

    # Skip comment lines
    if (substr(trimmed_line, 1, 1) == "#") {
        next
    }

    # Check for optional "export " prefix
    work = trimmed_line
    has_export = 0
    if (substr(work, 1, 7) == "export ") {
        has_export = 1
        work = substr(work, 8)
    } else if (substr(work, 1, 6) == "export") {
        print FILENAME ":" lineno ": invalid line" > "/dev/stderr"
        invalid = 1
        exit 1
    }

    # Now work should be KEY=VALUE
    eq_pos = index(work, "=")
    if (eq_pos == 0) {
        print FILENAME ":" lineno ": invalid line" > "/dev/stderr"
        invalid = 1
        exit 1
    }

    key = substr(work, 1, eq_pos - 1)
    raw_value = substr(work, eq_pos + 1)

    # Validate key: must match [A-Za-z_][A-Za-z0-9_]*
    if (key == "") {
        print FILENAME ":" lineno ": invalid line" > "/dev/stderr"
        invalid = 1
        exit 1
    }

    valid_key = 1
    for (k = 1; k <= length(key); k++) {
        ck = substr(key, k, 1)
        if (k == 1) {
            if (!((ck ~ /[A-Za-z_]/))) {
                valid_key = 0
                break
            }
        } else {
            if (!((ck ~ /[A-Za-z0-9_]/))) {
                valid_key = 0
                break
            }
        }
    }

    if (index(key, " ") > 0 || index(key, "\t") > 0) {
        valid_key = 0
    }

    if (!valid_key) {
        print FILENAME ":" lineno ": invalid line" > "/dev/stderr"
        invalid = 1
        exit 1
    }

    # Check for space before =
    if (eq_pos > 1 && substr(work, eq_pos - 1, 1) == " ") {
        print FILENAME ":" lineno ": invalid line" > "/dev/stderr"
        invalid = 1
        exit 1
    }

    # Check for space after =
    if (length(work) > eq_pos && substr(work, eq_pos + 1, 1) == " ") {
        print FILENAME ":" lineno ": invalid line" > "/dev/stderr"
        invalid = 1
        exit 1
    }

    # Process the value
    val = process_value(raw_value)
    if (val == "INVALID") {
        print FILENAME ":" lineno ": invalid line" > "/dev/stderr"
        invalid = 1
        exit 1
    }

    key_order[key] = lineno
    key_value[key] = val
}

END {
    if (invalid) exit 1

    # Get unique keys
    num_unique = 0
    for (k in key_order) {
        unique_keys[++num_unique] = k
    }

    # Sort unique_keys by key_order[k] using insertion sort
    for (i = 2; i <= num_unique; i++) {
        tmp_key = unique_keys[i]
        tmp_lineno = key_order[tmp_key]
        j = i - 1
        while (j >= 1 && key_order[unique_keys[j]] > tmp_lineno) {
            unique_keys[j + 1] = unique_keys[j]
            j--
        }
        unique_keys[j + 1] = tmp_key
    }

    for (i = 1; i <= num_unique; i++) {
        k = unique_keys[i]
        v = key_value[k]

        # Escape single quotes in value: replace '\'' with '\''\\'\''\'''
        gsub(/\047/, "\047\\\047\047", v)

        printf "export \047%s\047=\n", v
    }
}
' FILENAME="$FILE" "$FILE"

exit $?
